using Campfire.Modules.StrangerChat.Application; using Campfire.Modules.StrangerChat.Application.Abstractions; using Campfire.Modules.StrangerChat.Infrastructure.Persistence; using Campfire.Modules.StrangerChat.Infrastructure.Realtime; using Campfire.Modules.StrangerChat.Infrastructure.Services; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Configuration; using Microsoft.Extensions.DependencyInjection;
namespace Campfire.Modules.StrangerChat.Infrastructure;
public static class DependencyInjection { public static IServiceCollection AddStrangerChatModule(this IServiceCollection services,IConfiguration configuration){var cs=configuration.GetConnectionString("Campfire")??throw new InvalidOperationException("Connection string 'Campfire' is not configured.");services.AddStrangerChatApplication();services.AddDbContext<StrangerChatDbContext>(o=>o.UseNpgsql(cs,x=>x.MigrationsHistoryTable("__EFMigrationsHistory",StrangerChatDbContext.Schema)));services.AddScoped<IStrangerChatService,EfStrangerChatService>();services.AddScoped<IStrangerNotificationPublisher,SignalRStrangerNotificationPublisher>();services.AddSingleton(TimeProvider.System);services.AddHostedService<StrangerChatRetentionWorker>();services.AddSignalR(o=>o.MaximumReceiveMessageSize=16*1024);services.AddHealthChecks().AddDbContextCheck<StrangerChatDbContext>("stranger-chat-database");return services;}}
